language "ix:native" edition "1-draft";
profile C = "quire.state.core/v1";
profile S = "quire.state.queries/v1";
profile G = "quire.state.graph/v1";
profile T = "quire.temporal.event-position.false-extension/v1";
profile F = "quire.temporal.fixed-sample.false-extension/v1";
profile W = "quire.temporal.timestamped-event.finite-window/v1";
profile P = "quire.protocol.finite-global/v1";
model M = "acme/orders";
protocol Flow using P over (view: M::Plain) on origin { role Service on M::Node; requires temporal ByEvent; requires temporal BySample; requires temporal ByTimestamp; run sequence Main { event Happened by Service as (happened: M::Plain) { happened.ready }; event HappenedAgain by Service as (happenedAgain: M::Plain) { happenedAgain.ready }; } finish Closed as (closed: M::Plain) { closed.ready }; }

language "ix:native" edition "1-draft";
profile C = "quire.state.core/v1";
profile S = "quire.state.queries/v1";
profile G = "quire.state.graph/v1";
profile T = "quire.temporal.event-position.false-extension/v1";


profile P = "quire.protocol.finite-global/v1";
model M = "acme/orders";
temporal ByEvent using T over (view: M::Widget) clock "event-clock" on each (trigger: M::Widget) when (trigger.code > 0) { capture saved: M::Widget = trigger; always[0,0] not holds(view.code > 0) }

language "ix:native" edition "1-draft";
profile C = "quire.state.core/v1";
profile S = "quire.state.queries/v1";
profile G = "quire.state.graph/v1";

profile F = "quire.temporal.fixed-sample.false-extension/v1";

profile P = "quire.protocol.finite-global/v1";
model M = "acme/orders";
temporal BySample using F over (view: M::Widget) clock "sample-clock" on origin { eventually[0,0] holds(view.code > 0) }

language "ix:native" edition "1-draft";
profile C = "quire.state.core/v1";
profile S = "quire.state.queries/v1";
profile G = "quire.state.graph/v1";


profile W = "quire.temporal.timestamped-event.finite-window/v1";
profile P = "quire.protocol.finite-global/v1";
model M = "acme/orders";
temporal ByTimestamp using W over (view: M::Widget) clock "timestamp-clock" on origin { eventually[0,0] holds(view.code > 0) }
